from fastapi import FastAPI, Body
from fastapi.testclient import TestClient
from typing import List, Annotated
import pytest

app = FastAPI()

@app.post("/test_validation_alias")
def read_list(
    p: Annotated[List[str], Body(embed=True, validation_alias="p_val_alias")],
):
    return {"p": p}

client = TestClient(app)

def test_validation_alias():
    response = client.post("/test_validation_alias", json={"p_val_alias": ["a", "b"]})
    assert response.status_code == 200
    assert response.json() == {"p": ["a", "b"]}

if __name__ == "__main__":
    try:
        test_validation_alias()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
